/// <summary>
/// Extension of table ProjTable
/// </summary>
[ExtensionOf(tableStr(ProjTable))]
public final class AVAProjTableDbt_Extension
{
}

Method.Source:
/// <summary>
/// Part of method projLinePropertyId() to check if Project has a ProjLinePropertyId
/// </summary>
/// <returns>ProjLinePropertyId</returns>
public ProjLinePropertyId avaGetProjLinePropertyId()
{
    ProjLinePropertyId avaProjLinePropertyId;

    avaProjLinePropertyId = (select ProjLinePropertySetup 
                                where ProjLinePropertySetup.ProjCode          == TableGroupAll::Table
                                    && ProjLinePropertySetup.ProjRelation      == this.ProjId
                                    && ProjLinePropertySetup.CategoryCode      == TableGroupAll::All
                                    && ProjLinePropertySetup.CategoryRelation  == '').LinePropertyId;

    avaProjLinePropertyId  = ProjLineProperty::find(avaProjLinePropertyId).LinePropertyId;

    return avaProjLinePropertyId;
}
